# -*- coding: utf-8 -*-
from _lib import s
TOOLEY62 = 'Tooley tr.62 (Ch.4): nhãn là giá trị bát phân; chuẩn dùng parity lẻ.'
S = [
 s(1, 'title', 'Aircraft Systems, Analog Systems & Digital Systems: Data Buses',
   'Title slide: "Aircraft Systems, Analog Systems & Digital Systems", subtitle "Data Buses", USTH logo and a glass cockpit photo.',
   'Slide tiêu đề: "Aircraft Systems, Analog Systems & Digital Systems", phụ đề "Data Buses" (bus dữ liệu), logo USTH và ảnh buồng lái kính.'),
 s(2, 'content', 'Why do we need a data bus in an aircraft?',
   'Left panel, no data bus: point-to-point connection; each sensor or computer (ADC, engine computer FADEC, landing gear sensor, fuel quantity sensor) is wired separately to every device that uses the data (EFIS, flight control computers ELAC/SEC/FAC, ECAM, FMS, other systems). Drawbacks: many cables, weight and complexity; difficult installation, maintenance and troubleshooting; hard to expand; high risk of wiring errors. Right panel, with a data bus: devices share one or more common buses (ARINC 429 basic avionics, ARINC 629 redundant, AFDX/ARINC 664 Ethernet, other buses MIL-STD-1553, ARINC 717); fewer cables, data shared among many devices, easier installation and fault isolation, easier expansion, standard protocols with error checking and bus monitoring. Bottom: six reasons: reduce wiring, weight and space; share data among devices; increase reliability and safety (Bus A primary, Bus B secondary); easier maintenance and fault isolation; easier expansion and upgrade; support several data types at suitable speed.',
   'Khung trái, không dùng bus: kết nối điểm-điểm; mỗi cảm biến hoặc máy tính (ADC, máy tính động cơ FADEC, cảm biến càng đáp, cảm biến lượng nhiên liệu) nối dây riêng tới từng thiết bị dùng dữ liệu (EFIS, máy tính điều khiển bay ELAC/SEC/FAC, ECAM, FMS, hệ khác). Nhược điểm: nhiều cáp, nặng và phức tạp; lắp đặt, bảo dưỡng, tìm lỗi khó; khó mở rộng; dễ sai dây. Khung phải, dùng bus: các thiết bị dùng chung một hoặc vài bus (ARINC 429 avionics cơ bản, ARINC 629 dự phòng, AFDX/ARINC 664 Ethernet, bus khác MIL-STD-1553, ARINC 717); ít cáp hơn, dữ liệu chia sẻ nhiều thiết bị, lắp đặt và cách ly lỗi dễ hơn, mở rộng dễ, giao thức chuẩn có kiểm lỗi và giám sát bus. Cuối slide: sáu lý do: giảm dây, khối lượng và không gian; chia sẻ dữ liệu; tăng tin cậy và an toàn (Bus A chính, Bus B phụ); bảo trì và cách ly lỗi dễ; mở rộng và nâng cấp dễ; hỗ trợ nhiều kiểu dữ liệu với tốc độ phù hợp.'),
 s(3, 'content', 'Data Buses in an Aircraft (Example: Airbus A320)',
   'Overview diagram of an A320 with sensors, the ADIRU, EFIS (PFD/ND), FMS, ECAM, flight control computers (ELAC/SEC/FAC) with actuators, cabin systems (CIDS), ACMS and engines (FADEC), joined by coloured lines: green ARINC 429, blue ARINC 629, red AFDX/ARINC 664, orange other buses (MIL-STD-1553, ARINC 717). Four cards. 1 ARINC 429: simple bus, low speed, high reliability; point-to-point simplex (1 transmitter to several receivers); 12.5 or 100 kbps; 32-bit word; bipolar return to zero (BPRZ). 2 ARINC 629: multi-drop, dual-redundant (Bus A primary, Bus B secondary); 2 Mbps; TDMA access. 3 AFDX/ARINC 664: switched Ethernet, 100 Mbps full duplex, Virtual Links with guaranteed bandwidth. 4 MIL-STD-1553 / ARINC 717: 1553B is a dual-redundant command-response bus (bus controller, remote terminal, bus monitor), 1 Mbps, used with FADEC; ARINC 717 data rate "2/4/8 Mbps", mainly CVR/FDR recording. Footer: modern aircraft use several buses in parallel, each chosen by data rate, reliability, real-time performance and data volume.',
   'Sơ đồ tổng quan một chiếc A320 với cảm biến, ADIRU, EFIS (PFD/ND), FMS, ECAM, máy tính điều khiển bay (ELAC/SEC/FAC) và cơ cấu chấp hành, hệ cabin (CIDS), ACMS và động cơ (FADEC), nối bằng các đường màu: xanh lá ARINC 429, xanh dương ARINC 629, đỏ AFDX/ARINC 664, cam các bus khác (MIL-STD-1553, ARINC 717). Bốn thẻ. 1 ARINC 429: bus đơn giản, tốc độ thấp, tin cậy cao; điểm-điểm đơn công (1 bộ phát tới nhiều bộ thu); 12,5 hoặc 100 kbps; từ 32 bit; mã lưỡng cực về không (BPRZ). 2 ARINC 629: nhiều điểm, dự phòng kép (Bus A chính, Bus B phụ); 2 Mbps; truy cập TDMA. 3 AFDX/ARINC 664: Ethernet chuyển mạch, 100 Mbps song công, Virtual Link có băng thông đảm bảo. 4 MIL-STD-1553 / ARINC 717: 1553B là bus dự phòng kép kiểu lệnh-đáp (bộ điều khiển bus, thiết bị đầu cuối, bộ giám sát), 1 Mbps, dùng với FADEC; ARINC 717 ghi tốc độ "2/4/8 Mbps", chủ yếu cho CVR/FDR. Chân slide: máy bay hiện đại dùng nhiều bus song song, mỗi bus chọn theo tốc độ, độ tin cậy, thời gian thực và khối lượng dữ liệu.',
   numbers=['ARINC 429: 12,5 hoặc 100 kbps, từ 32 bit', 'ARINC 629: 2 Mbps', 'AFDX: 100 Mbps', 'MIL-STD-1553B: 1 Mbps', 'ARINC 717: 2/4/8 Mbps (theo slide)'],
   issues=['Nghi vấn (chưa kiểm được): slide ghi ARINC 717 có tốc độ 2/4/8 Mbps. Tooley tr.66 chỉ nói ARINC 717 thay ARINC 573 và "có nhiều tốc độ bit và cỡ khung", không nêu con số; thư mục không có tài liệu ARINC 717 để đối chiếu.',
           'Nghi vấn: AFDX xuất hiện trong sơ đồ A320, trong khi Module 05 gắn AFDX với A380/A350 (chưa kiểm lại bằng Tooley Ch.16); slide 7 cũng nói "A380 và A350 (và một vài hệ trên A320)". Cần hỏi giảng viên.']),
 s(4, 'content', 'A320 - Connection between major LRUs',
   'Block diagram of A320 LRU groups above and below three horizontal buses: AFDX network (ARINC 664) as a high-speed Ethernet backbone with redundant networks A and B; ARINC 429 buses (low-speed point-to-point); ARINC 629 data bus (medium-speed, dual redundant, Bus A and Bus B). Top groups: flight control (ELAC, SEC, FAC), flight management (FMGC, MCDU, FCU), air data/inertial (ADIRU), display/warning (DMC, DU, FWC), communication (VHF, HF, AMU, RMP). Bottom groups: navigation (MMR, DME, ADF, radio altimeter, weather radar), engine (EEC 1, 2), electrical (GCU, BCL, GPCU), air conditioning (pack and zone controllers), landing gear/brakes (LGCIU, BSCU), fuel, maintenance (CFDIU, DMU). Three boxes: bus legend (AFDX 100 Mbps switched redundant; ARINC 429 low speed 12.5/100 kbps point-to-point; ARINC 629 medium speed 2 Mbps dual redundant; discrete/analog signals; audio signals), example connections (for instance ADIRU to FMGC via ARINC 429, FMGC to MCDU/FCU via AFDX), typical LRU locations in the avionics compartments.',
   'Sơ đồ khối các nhóm LRU của A320 nằm trên và dưới ba bus ngang: mạng AFDX (ARINC 664) là xương sống Ethernet tốc độ cao với hai mạng dự phòng A và B; các bus ARINC 429 (điểm-điểm tốc độ thấp); bus dữ liệu ARINC 629 (tốc độ trung bình, dự phòng kép, Bus A và Bus B). Nhóm phía trên: điều khiển bay (ELAC, SEC, FAC), quản lý bay (FMGC, MCDU, FCU), dữ liệu không khí/quán tính (ADIRU), hiển thị/cảnh báo (DMC, DU, FWC), liên lạc (VHF, HF, AMU, RMP). Nhóm phía dưới: dẫn đường (MMR, DME, ADF, đo cao vô tuyến, radar thời tiết), động cơ (EEC 1, 2), điện (GCU, BCL, GPCU), điều hoà (điều khiển pack và vùng), càng/phanh (LGCIU, BSCU), nhiên liệu, bảo dưỡng (CFDIU, DMU). Ba khung: chú giải bus (AFDX 100 Mbps chuyển mạch dự phòng; ARINC 429 tốc độ thấp 12,5/100 kbps điểm-điểm; ARINC 629 tốc độ trung bình 2 Mbps dự phòng kép; tín hiệu rời rạc/tương tự; tín hiệu âm thanh), các kết nối ví dụ (như ADIRU tới FMGC qua ARINC 429, FMGC tới MCDU/FCU qua AFDX), vị trí LRU điển hình trong các khoang avionics.',
   issues=['Nghi vấn như slide 3: sơ đồ A320 có mạng AFDX làm xương sống; cần đối chiếu với tài liệu hãng (không có trong thư mục).']),
 s(5, 'content', 'Airbus A320 - ARINC 629 Network (Only)',
   'A diagram with ARINC 629 Bus A (redundant bus A) and Bus B (redundant bus B), each medium speed 2 Mbps, point-to-point with a bus coupler for each LRU. LRUs above and below the buses, each with Tx and Rx boxes: ELAC, SEC, FAC (flight control), FMGC (flight management), LGCIU (landing gear), BSCU (brakes), ADIRU, GCU, BCL, GPCU (electrical), EEC (engine), pack and zone controllers, fuel control unit, FWC, DMC, CFDIU, DMU, TCAS and weather radar (if installed). Legend: Tx = transmitter, Rx = receiver, bus coupling unit. Key points: dual redundant bus A and B; medium speed 2 Mbps; point-to-point architecture (daisy-chain) with bus couplers; each LRU can be transmitter, receiver or both; supports real-time system data; mainly used for system and sensor data between avionics LRUs (no AFDX, no ARINC 429 in this diagram). Example data flow: LGCIU (Tx) sends landing gear position data over ARINC 629 (2 Mbps) to DMC (Rx), which displays landing gear status.',
   'Sơ đồ có ARINC 629 Bus A (bus dự phòng A) và Bus B (bus dự phòng B), mỗi bus tốc độ trung bình 2 Mbps, điểm-điểm với bộ ghép bus cho từng LRU. Các LRU nằm trên và dưới bus, mỗi LRU có ô Tx và Rx: ELAC, SEC, FAC (điều khiển bay), FMGC (quản lý bay), LGCIU (càng), BSCU (phanh), ADIRU, GCU, BCL, GPCU (điện), EEC (động cơ), điều khiển pack và vùng, bộ điều khiển nhiên liệu, FWC, DMC, CFDIU, DMU, TCAS và radar thời tiết (nếu lắp). Chú giải: Tx = bộ phát, Rx = bộ thu, bộ ghép bus. Điểm chính: bus kép A và B dự phòng; tốc độ trung bình 2 Mbps; kiến trúc điểm-điểm (nối chuỗi) với bộ ghép bus; mỗi LRU có thể phát, thu hoặc cả hai; hỗ trợ dữ liệu hệ thống thời gian thực; chủ yếu dùng cho dữ liệu hệ thống và cảm biến giữa các LRU avionics (sơ đồ này không có AFDX và ARINC 429). Ví dụ luồng dữ liệu: LGCIU (Tx) gửi vị trí càng qua ARINC 629 (2 Mbps) tới DMC (Rx) để hiển thị trạng thái càng.',
   numbers=['ARINC 629: 2 Mbps, Bus A và Bus B'], issues=['Không khớp với Tooley: slide mô tả một chiếc A320 với mạng ARINC 629 ("only"). Tooley tr.66 (mục 4.3.6) nói ARINC 629 hiện dùng trên Boeing 777, Airbus A330 và A340, còn tr.59 liệt kê A310/A320 trong các máy bay lắp ARINC 429.']),
 s(6, 'content', 'ARINC 629 overview, architecture and characteristics',
   'Eight panels. 1 Overview: ARINC 629 is a high-speed serial digital data bus standard developed for Airbus aircraft (A320, A330, A340, A380) by ARINC; it lets several LRUs communicate through two independent buses A and B with real-time access using TDMA; data rate 2 Mbps; used for central avionics systems with high data needs. 2 Network architecture on A320: ADIRU, FMGS, ELAC, FAC, SEC, ECAM on bus A (2 Mbps) and bus B (2 Mbps), plus ACMS, CFDIU, CIDS, SDAC, ATC/TCAS and other LRUs. 3 Physical structure: each bus with a 78 ohm termination at both ends, LRU 1 to LRU n; transmission differential, twisted and shielded pair. 4 Message frame: Sync 8 bits, Data 32 bits (4 bytes), SDI 2 bits, Label 8 bits, SSM 2 bits, total 52 bits. 5 TDMA channel access: a major frame of 125 slots of 16 us each, major frame cycle 2 ms; each LRU transmits in its assigned slot. 6 Example waveform: Bus A (+) and Bus A (-) between +5 V and -5 V, differential voltage Vdiff = 10 V. 7 Key characteristics table: 2 Mbps, differential twisted shielded pair, two buses, TDMA, frame length 52 bits, 125 slots per major frame, slot duration 16 us, major frame cycle 2 ms, up to 20-21 LRUs on one bus. 8 Applications on A320: ELAC/SEC/FAC to ADIRU for attitude and speed; FMGS to ECAM for flight phase and warnings; others.',
   'Tám khung. 1 Tổng quan: ARINC 629 là chuẩn bus dữ liệu số nối tiếp tốc độ cao do ARINC phát triển cho máy bay Airbus (A320, A330, A340, A380); cho nhiều LRU liên lạc qua hai bus độc lập A và B với truy cập thời gian thực bằng TDMA; tốc độ 2 Mbps; dùng cho hệ avionics trung tâm có nhu cầu dữ liệu lớn. 2 Kiến trúc mạng trên A320: ADIRU, FMGS, ELAC, FAC, SEC, ECAM trên bus A (2 Mbps) và bus B (2 Mbps), cùng ACMS, CFDIU, CIDS, SDAC, ATC/TCAS và LRU khác. 3 Cấu trúc vật lý: mỗi bus có điện trở kết cuối 78 ôm ở hai đầu, LRU 1 tới LRU n; truyền vi sai, cặp xoắn có bọc. 4 Khung tin: Sync 8 bit, Data 32 bit (4 byte), SDI 2 bit, Label 8 bit, SSM 2 bit, tổng 52 bit. 5 Truy cập kênh TDMA: một khung lớn gồm 125 khe, mỗi khe 16 us, chu kỳ khung lớn 2 ms; mỗi LRU phát trong khe được giao. 6 Dạng sóng ví dụ: Bus A (+) và Bus A (-) giữa +5 V và -5 V, điện áp vi sai Vdiff = 10 V. 7 Bảng đặc tính: 2 Mbps, cặp xoắn bọc vi sai, hai bus, TDMA, khung 52 bit, 125 khe mỗi khung lớn, khe 16 us, chu kỳ khung lớn 2 ms, tối đa 20-21 LRU trên một bus. 8 Ứng dụng trên A320: ELAC/SEC/FAC tới ADIRU cho tư thế và tốc độ; FMGS tới ECAM cho pha bay và cảnh báo; khác.',
   formulas=['125 x 16 us = 2 ms', '8 + 32 + 2 + 8 + 2 = 52 bit'], numbers=['2 Mbps', '78 ohm', '52 bit', '125 khe x 16 us = 2 ms', '+5 V / -5 V, Vdiff = 10 V'],
   issues=['Đã kiểm: 125 khe x 16 us = 2 ms và 8 + 32 + 2 + 8 + 2 = 52 bit đều khớp.',
           'Không khớp với Tooley (tr.66, mục 4.3.6): ARINC 629 hỗ trợ 120 thiết bị nối trên bus và hiện dùng trên Boeing 777, Airbus A330 và A340; slide ghi "tối đa 20-21 LRU trên một bus" và gắn thêm A320 và A380.']),
 s(7, 'content', 'ARINC 664 (AFDX): overview, frame, virtual link, bandwidth',
   'Seven panels. 1 Overview: ARINC 664 (Part 7) defines Ethernet technology for aircraft; AFDX is its implementation, used on Airbus (A380, A350, and some systems on A320); switched Ethernet at 100 Mbps full duplex; quality of service through Virtual Links and deterministic communication; real-time and safety-critical; carries large data such as images, video, maintenance data. 2 AFDX network architecture on an A350 example: ADIRU, FMS, CFDIU, CIDS, IFE and a maintenance system joined to redundant AFDX switches, with flight control computers, ECAM display, cabin systems, brakes and engines (FADEC) on the switches, and external connections (SATCOM, airport network, ground data loading). 3 Frame structure based on Ethernet (64 to 1518 bytes): preamble 7 bytes, SFD 1 byte, destination MAC 6, source MAC 6, EtherType 2, payload 46 to 1500 bytes (virtual link data), FCS 4 bytes (CRC 32). 4 Virtual Link: a logical connection between a source and a destination; each VL has its own bandwidth, frame size, transmission period (BAG) and priority; the switch isolates VLs by per-VL policing. 5 Bandwidth and QoS: BAG is the minimum interval between two consecutive frames of a VL; it limits bandwidth and prevents congestion. 6 Key characteristics: 100 Mbps, switched Ethernet full duplex, VL plus BAG, frame length 64 to 1518 bytes, deterministic, two independent networks A and B, typical number of VLs up to 20-21 (as read). 7 Advantages and applications on Airbus.',
   'Bảy khung. 1 Tổng quan: ARINC 664 (Phần 7) quy định công nghệ Ethernet cho máy bay; AFDX là bản triển khai, dùng trên Airbus (A380, A350 và một vài hệ trên A320); Ethernet chuyển mạch 100 Mbps song công; chất lượng dịch vụ nhờ Virtual Link và truyền thông xác định; thời gian thực và an toàn; truyền dữ liệu lớn như ảnh, video, dữ liệu bảo dưỡng. 2 Kiến trúc mạng AFDX (ví dụ A350): ADIRU, FMS, CFDIU, CIDS, IFE và hệ bảo dưỡng nối vào các bộ chuyển mạch AFDX dự phòng, cùng máy tính điều khiển bay, màn hình ECAM, hệ cabin, phanh và động cơ (FADEC), và kết nối ngoài (SATCOM, mạng sân bay, nạp dữ liệu mặt đất). 3 Cấu trúc khung dựa trên Ethernet (64 đến 1518 byte): preamble 7 byte, SFD 1 byte, MAC đích 6, MAC nguồn 6, EtherType 2, payload 46 đến 1500 byte (dữ liệu virtual link), FCS 4 byte (CRC 32). 4 Virtual Link: kết nối logic giữa nguồn và đích; mỗi VL có băng thông, cỡ khung, chu kỳ truyền (BAG) và độ ưu tiên riêng; bộ chuyển mạch cách ly VL bằng kiểm soát theo VL. 5 Băng thông và QoS: BAG là khoảng cách tối thiểu giữa hai khung liên tiếp của một VL; hạn chế băng thông và tránh tắc nghẽn. 6 Đặc tính: 100 Mbps, Ethernet chuyển mạch song công, VL cộng BAG, khung 64 đến 1518 byte, xác định, hai mạng độc lập A và B, số VL điển hình tới 20-21 (theo đọc). 7 Ưu điểm và ứng dụng trên Airbus.',
   numbers=['100 Mbps', 'khung 64 đến 1518 byte', 'preamble 7 + SFD 1 + MAC 6 + 6 + EtherType 2 + payload 46 đến 1500 + FCS 4'],
   issues=['Đã kiểm: 7 + 1 + 6 + 6 + 2 + 46 + 4 = 72 byte kể cả preamble và SFD, tức khung Ethernet tối thiểu 64 byte (không tính preamble và SFD); khớp với "64 đến 1518".',
           'Nghi vấn: "số VL điển hình tới 20-21" (đọc ở độ phóng đại thấp, chữ nhỏ) có vẻ quá nhỏ cho một mạng AFDX; cần đọc lại slide gốc ở độ phân giải cao trước khi dùng.']),
 s(8, 'divider', 'ARINC 429', 'Section divider slide with the single title "ARINC 429".', 'Slide ngăn phần chỉ có tiêu đề "ARINC 429".'),
 s(9, 'content', 'Airbus A320 - ARINC 429 connections (transmitter and receiver)',
   'Block diagram: LRU groups above and below ARINC 429 BUS A and BUS B (low-speed, unidirectional, point-to-point links between LRUs); every LRU box has Tx and Rx markers. Top groups: flight control (ELAC, SEC, FAC), flight management (FMGC, MCDU, FCU), air data/inertial (ADIRU), display/warning (DMC, DU, FWC), communication (VHF, HF, AMU, RMP). Bottom groups: navigation, engine (EEC 1, 2), electrical, air conditioning, landing gear/brakes, fuel, maintenance/data. Legend: Tx sends data on a specific channel, Rx receives; each LRU can have several Tx and Rx channels. Example ADIRU to FMGC: ARINC 429 carries air data (speed, altitude, Mach number); ADIRU is the transmitter, FMGC the receiver. A table lists typical transmitted data and main receivers, for example ADIRU: speed, altitude, Mach, to FMGC, FWC, DMC; MMR: navigation data, to FMGC, FCU, DMC; EEC: engine parameters, to FMGC, FWC; FMGC: flight plan and guidance data, to MCDU, FCU, DMC; FWC: ECAM warnings, to DMC (to DU); GCU: generator status, to FWC, CFDIU; LGCIU: landing gear status, to FWC, CFDIU; pack controller: air conditioning status, to FWC, CFDIU.',
   'Sơ đồ khối: các nhóm LRU nằm trên và dưới ARINC 429 BUS A và BUS B (liên kết điểm-điểm một chiều tốc độ thấp giữa các LRU); mỗi LRU có ký hiệu Tx và Rx. Nhóm trên: điều khiển bay (ELAC, SEC, FAC), quản lý bay (FMGC, MCDU, FCU), dữ liệu không khí/quán tính (ADIRU), hiển thị/cảnh báo (DMC, DU, FWC), liên lạc (VHF, HF, AMU, RMP). Nhóm dưới: dẫn đường, động cơ (EEC 1, 2), điện, điều hoà, càng/phanh, nhiên liệu, bảo dưỡng/dữ liệu. Chú giải: Tx gửi dữ liệu trên một kênh, Rx nhận; mỗi LRU có thể có nhiều kênh Tx và Rx. Ví dụ ADIRU tới FMGC: ARINC 429 mang dữ liệu không khí (tốc độ, độ cao, số Mach); ADIRU là bộ phát, FMGC là bộ thu. Bảng liệt kê dữ liệu phát điển hình và bộ thu chính, ví dụ ADIRU: tốc độ, độ cao, Mach, tới FMGC, FWC, DMC; MMR: dữ liệu dẫn đường, tới FMGC, FCU, DMC; EEC: thông số động cơ, tới FMGC, FWC; FMGC: kế hoạch bay và dẫn hướng, tới MCDU, FCU, DMC; FWC: cảnh báo ECAM, tới DMC (rồi DU); GCU: trạng thái máy phát, tới FWC, CFDIU; LGCIU: trạng thái càng, tới FWC, CFDIU; điều khiển pack: trạng thái điều hoà, tới FWC, CFDIU.'),
 s(10, 'content', 'ARINC 429 - Data communication standard in aircraft',
   'Nine panels. 1 Overview: point-to-point data standard developed by ARINC, used in Airbus A320 and Boeing 737/777; data rate 12.5 kbps (mainly) or 100 kbps; one transmitter can connect to at most 20 receivers; differential signalling with bipolar return to zero (BPRZ) encoding; shielded twisted pair. 2 Example connection: ADIRU transmits over ARINC 429 (one way) to EFIS (PFD/ND), FMS and other systems; one transmitter can feed up to 20 receivers but only one direction. 3 Cable: differential signalling on two wires A and B of opposite polarity, reduces EMI, shielded; typical cable impedance 70 to 85 ohm (usually 78 ohm). 4 Data word format, total 32 bits (4 bytes), Label 8 bits (bit 1 to 8), SDI 2 bits, Data 19 bits, SSM 2 bits, Parity 1 bit; label identifies data type (for example 203 = IAS), parity is "even parity". 5 BPRZ encoding: bit 1: Tx+ positive and Tx- negative (about +-10 V) then both return to 0 V in the middle of the bit period; bit 0: Tx+ negative and Tx- positive then return to 0 V. 6 Example, transmit airspeed IAS: label 203 (0xCB), SDI 0, data 0x1F4 (for example 500 kt, depending on format), SSM 00 normal operation, even parity bit; label 1100 1011, SDI 00, data 00000011110100, SSM 00, P 0. 7 Data rate and bit timing: 12.5 kbps gives bit time 80 us and word time 2.56 ms; 100 kbps gives 10 us and 0.32 ms. 8 SSM values (example): 00 normal operation (valid data), 01 no computed data (not valid), 10 functional test (in test mode), 11 failure (fault). 9 Advantages and disadvantages.',
   'Chín khung. 1 Tổng quan: chuẩn dữ liệu điểm-điểm do ARINC phát triển, dùng trên Airbus A320 và Boeing 737/777; tốc độ 12,5 kbps (chủ yếu) hoặc 100 kbps; một bộ phát nối tối đa 20 bộ thu; tín hiệu vi sai, mã lưỡng cực về không (BPRZ); cặp xoắn có bọc. 2 Ví dụ kết nối: ADIRU phát qua ARINC 429 (một chiều) tới EFIS (PFD/ND), FMS và hệ khác; một bộ phát cấp được tới 20 bộ thu nhưng chỉ một chiều. 3 Cáp: tín hiệu vi sai trên hai dây A và B ngược cực, giảm EMI, có bọc; trở kháng cáp điển hình 70 đến 85 ôm (thường 78 ôm). 4 Định dạng từ dữ liệu, tổng 32 bit (4 byte), Label 8 bit (bit 1 đến 8), SDI 2 bit, Data 19 bit, SSM 2 bit, Parity 1 bit; label cho biết loại dữ liệu (ví dụ 203 = IAS), parity là "even parity" (chẵn). 5 Mã hoá BPRZ: bit 1: Tx+ dương và Tx- âm (khoảng +-10 V) rồi cả hai về 0 V ở giữa chu kỳ bit; bit 0: Tx+ âm và Tx- dương rồi về 0 V. 6 Ví dụ phát tốc độ IAS: label 203 (0xCB), SDI 0, data 0x1F4 (ví dụ 500 kt, tuỳ định dạng), SSM 00 hoạt động bình thường, bit parity chẵn; label 1100 1011, SDI 00, data 00000011110100, SSM 00, P 0. 7 Tốc độ và định thời bit: 12,5 kbps cho thời gian bit 80 us và thời gian từ 2,56 ms; 100 kbps cho 10 us và 0,32 ms. 8 Giá trị SSM (ví dụ): 00 hoạt động bình thường (dữ liệu hợp lệ), 01 không có dữ liệu tính (không hợp lệ), 10 thử chức năng (chế độ thử), 11 hỏng. 9 Ưu và nhược điểm.',
   formulas=['32 x 80 us = 2,56 ms', '32 x 10 us = 0,32 ms'], numbers=['12,5 kbps: bit 80 us, từ 2,56 ms', '100 kbps: bit 10 us, từ 0,32 ms', 'tối đa 20 bộ thu', 'trở kháng cáp 70 đến 85 ôm (thường 78 ôm)'],
   issues=['Đã kiểm: 32 x 80 us = 2,56 ms; 32 x 10 us = 0,32 ms; 0xCB = 1100 1011; 0x1F4 = 500 thập phân.',
           'Không khớp với Tooley: slide ghi parity chẵn (even), trong khi ' + TOOLEY62 + ' Slide 15 và 17 của cùng bộ ghi parity lẻ (odd).',
           'Không khớp với Tooley: slide ghi "label 203 (0xCB)" như số thập phân đổi sang hex; ' + TOOLEY62 + ' Trường hợp 203 là bát phân sẽ ứng với 1000 0011.',
           'Không khớp nội bộ: bảng SSM (00 bình thường, 11 hỏng) ngược với slide 15 và 17 của cùng bộ (00 hỏng, 11 bình thường, các giá trị cho dữ liệu BNR). Tooley trong thư mục không có bảng SSM nên chưa phân xử được từ nguồn.']),
 s(11, 'content', 'Why can one LRU be both a transmitter (Tx) and a receiver (Rx) in ARINC 429?',
   'An LRU in an A320 usually needs to send its own data to other LRUs (act as Tx) and receive data from others (act as Rx), so most LRUs have multiple channels. ARINC 429 is a point-to-point unidirectional bus: one Tx to multiple Rx; to exchange data between two LRUs two separate channels are needed: channel 1 LRU A transmits to LRU B (A to B), channel 2 LRU B transmits to LRU A (B to A); so an LRU usually has both Tx and Rx channels. Number of channels: each LRU can have several Tx and Rx channels; an ADIRU can have many Tx channels and many Rx channels; the number depends on the LRU design. The same LRU-group diagram with Bus A and Bus B as slide 9. Example 1: ADIRU to FMGC (channel 1, air data and IR data) and FMGC to ADIRU (channel 2, mode selection, input data). Example 2: MCDU as transmitter (flight plan data, INIT data, pilot commands, maintenance test commands) and receiver (data from FMGC, CFDs, status information). Example 3: ADIRU with channels Tx1 air data (ADR) to FMGC, FWC, DMC, ECAM; Tx2 inertial data (IR); Tx3 heading/attitude; Rx1 selected modes from FMGC; Rx2 IRS alignment command from MCDU/CFDIU; Rx3 maintenance data from CFDIU; Rx4 other commands.',
   'Một LRU trên A320 thường cần gửi dữ liệu của mình cho LRU khác (đóng vai Tx) và nhận dữ liệu từ LRU khác (đóng vai Rx), nên hầu hết LRU có nhiều kênh. ARINC 429 là bus điểm-điểm một chiều: một Tx tới nhiều Rx; để trao đổi giữa hai LRU cần hai kênh riêng: kênh 1 LRU A phát tới LRU B (A tới B), kênh 2 LRU B phát tới LRU A (B tới A); vì vậy một LRU thường có cả kênh Tx và Rx. Số kênh: mỗi LRU có thể có nhiều kênh Tx và Rx; ADIRU có thể có nhiều kênh Tx và nhiều kênh Rx; số kênh phụ thuộc thiết kế LRU. Sơ đồ nhóm LRU với Bus A và Bus B như slide 9. Ví dụ 1: ADIRU tới FMGC (kênh 1, dữ liệu không khí và IR) và FMGC tới ADIRU (kênh 2, chọn chế độ, dữ liệu nhập). Ví dụ 2: MCDU là bộ phát (dữ liệu kế hoạch bay, dữ liệu INIT, lệnh phi công, lệnh thử bảo dưỡng) và bộ thu (dữ liệu từ FMGC, CFD, thông tin trạng thái). Ví dụ 3: ADIRU với các kênh Tx1 dữ liệu không khí (ADR) tới FMGC, FWC, DMC, ECAM; Tx2 dữ liệu quán tính (IR); Tx3 hướng/tư thế; Rx1 chế độ chọn từ FMGC; Rx2 lệnh căn chỉnh IRS từ MCDU/CFDIU; Rx3 dữ liệu bảo dưỡng từ CFDIU; Rx4 lệnh khác.'),
 s(12, 'content', 'Example: ARINC 429 data transmission between transmitter and receiver in A320',
   'Six panels on sending indicated airspeed (IAS) from ADIRU to PFD. 1 Connection: pitot and static pressure sensors feed the ADIRU (transmitter) which sends over a one-way ARINC 429 bus to the PFD (receiver), shown on the airspeed tape. 2 Data to be transmitted: parameter IAS, label (hex) 215 (for example using label 215), value 250 kt, data format BCD, source ADIRU, receiver PFD and other devices. 3 Data encoding: 250 kt in BCD, 2 gives 0010, 5 gives 0101, 0 gives 0000; 19-bit data 0000 0000 0010 0101 000 (remaining bits 0); label 215 (hex) = 1000 0101 (binary); SDI = 00 (sent to all receivers). 4 Word structure (32 bits): Label (8 bits) 215 (1000 0101), SDI 00, Data (19 bits) BCD for 250 kt, SSM 00 (normal), Parity P; complete word 1000 0101 00 0000 0000 0010 0101 000 00 P. 5 Transmission on the bus: continuous transmission of ARINC 429 words (for example every 100 ms) on a twisted-shielded pair at +-10 V, 12.5 or 100 kbps. 6 Decoding at the receiver: receive the signal, check parity, decode label (215 = indicated airspeed), data (BCD 250 = 250 kt) and SSM (00 = valid data), update the PFD (250 kt shown). Notes: one-way bus; the same data can be received by several devices; each parameter has its own label and uses BCD or BNR.',
   'Sáu khung về việc gửi tốc độ chỉ thị (IAS) từ ADIRU tới PFD. 1 Kết nối: đầu đo áp suất pitot và tĩnh cấp cho ADIRU (bộ phát) rồi gửi qua bus ARINC 429 một chiều tới PFD (bộ thu), hiển thị trên thang tốc độ. 2 Dữ liệu cần truyền: thông số IAS, label (hex) 215 (ví dụ dùng label 215), giá trị 250 kt, định dạng BCD, nguồn ADIRU, bộ thu PFD và thiết bị khác. 3 Mã hoá dữ liệu: 250 kt dạng BCD, 2 là 0010, 5 là 0101, 0 là 0000; dữ liệu 19 bit 0000 0000 0010 0101 000 (các bit còn lại bằng 0); label 215 (hex) = 1000 0101 (nhị phân); SDI = 00 (gửi cho mọi bộ thu). 4 Cấu trúc từ (32 bit): Label (8 bit) 215 (1000 0101), SDI 00, Data (19 bit) BCD cho 250 kt, SSM 00 (bình thường), Parity P; từ đầy đủ 1000 0101 00 0000 0000 0010 0101 000 00 P. 5 Truyền trên bus: truyền liên tục các từ ARINC 429 (ví dụ mỗi 100 ms) trên cặp xoắn có bọc ở +-10 V, 12,5 hoặc 100 kbps. 6 Giải mã ở bộ thu: nhận tín hiệu, kiểm parity, giải mã label (215 = tốc độ chỉ thị), data (BCD 250 = 250 kt) và SSM (00 = dữ liệu hợp lệ), cập nhật PFD (hiện 250 kt). Ghi chú: bus một chiều; cùng dữ liệu có thể được nhiều thiết bị thu; mỗi thông số có label riêng và dùng BCD hoặc BNR.',
   numbers=['IAS 250 kt = BCD 0010 0101 0000', 'từ 1000 0101 00 0000 0000 0010 0101 000 00 P'],
   issues=['Không khớp trong slide (đã xác nhận ở độ phóng đại 4 lần): "Label 215 (hex) = 1000 0101 (binary)". 1000 0101 là 0x85, tức 133 thập phân hay 205 bát phân; 215 hex cần 10 bit; 215 bát phân là 1000 1101. Không cách đọc nào của "215" cho 1000 0101.',
           'Đã kiểm: 8 + 2 + 19 + 2 + 1 = 32 bit và trường data 0000 0000 0010 0101 000 đúng 19 chữ số.',
           'Không khớp với Tooley: ' + TOOLEY62 + ' (slide chỉ ghi "P" chưa nói chẵn hay lẻ ở slide này).']),
 s(13, 'content', 'ARINC 429 - Bipolar Return-to-Zero (BPRZ) signal: why does each bit return to zero?',
   'Six panels. 1 Voltage levels: HI (1) is +5 V on wire A and -5 V on wire B, differential +10 V, meaning bit 1; NULL is 0 V on both, differential 0 V, no data; LO (0) is -5 V on A and +5 V on B, differential -10 V, bit 0; the receiver only cares about the differential voltage VA - VB. 2 Waveform of each bit: bit 1, bit 0 and NULL drawn against bit time. 3 Example: the bit sequence 1 0 1 1 0 0 1 0 shown on wire A, wire B and the differential voltage (+10 V to -10 V). 4 Comparison with and without return to zero: NRZ (not used in ARINC 429) holds +10 V for a long sequence of 1s with no transitions, hard to synchronise; BPRZ (used in ARINC 429) returns to 0 V each bit, a transition in every bit, easy to synchronise. 5 Gap between words: after 32 bits the transmitter keeps the NULL level for at least 4 bit-times. 6 Advantages of return-to-zero: self-clocking; clear separation between consecutive bits; clear gap between words (NULL for at least 4 bit-times after 32 bits); reduces the impact of DC offset and improves noise immunity; NULL is an intermediate state, not a valid bit value.',
   'Sáu khung. 1 Mức điện áp: HI (1) là +5 V trên dây A và -5 V trên dây B, vi sai +10 V, nghĩa là bit 1; NULL là 0 V trên cả hai, vi sai 0 V, không có dữ liệu; LO (0) là -5 V trên A và +5 V trên B, vi sai -10 V, bit 0; bộ thu chỉ quan tâm điện áp vi sai VA - VB. 2 Dạng sóng mỗi bit: bit 1, bit 0 và NULL vẽ theo thời gian bit. 3 Ví dụ: dãy bit 1 0 1 1 0 0 1 0 trên dây A, dây B và điện áp vi sai (+10 V đến -10 V). 4 So sánh có và không về không: NRZ (ARINC 429 không dùng) giữ +10 V suốt chuỗi bit 1, không có chuyển mức, khó đồng bộ; BPRZ (ARINC 429 dùng) về 0 V ở mỗi bit, mỗi bit có một chuyển mức, dễ đồng bộ. 5 Khoảng cách giữa các từ: sau 32 bit bộ phát giữ mức NULL ít nhất 4 thời gian bit. 6 Ưu điểm của về-không: tự đồng hồ; tách rõ các bit liên tiếp; khoảng cách rõ giữa các từ (NULL ít nhất 4 thời gian bit sau 32 bit); giảm ảnh hưởng của lệch DC và tăng chống nhiễu; NULL là trạng thái trung gian, không phải giá trị bit hợp lệ.',
   numbers=['HI: A +5 V, B -5 V, vi sai +10 V', 'LO: A -5 V, B +5 V, vi sai -10 V', 'khoảng NULL giữa các từ: ít nhất 4 thời gian bit'],
   issues=['Slide này mô tả đúng BPRZ; slide 14 và 15 của cùng bộ lại ghi "Manchester Biphase-L" cho ARINC 429 (xem các slide đó).']),
 s(14, 'content', 'ARINC 429 - Bit encoding example and electrical characteristics',
   'Four panels. 1 Bit encoding (Fig. 1): bit 1 (high) and bit 0 (low) drawn on Line A and Line B over 10 us; text: ARINC 429 uses Manchester Biphase-L encoding; each bit has a transition at the middle of the bit period (5 us); bit 1: Line A at high level (+V), Line B low (-V) for the first half of the bit; bit 0: the reverse; each bit lasts 10 us, corresponding to 100 kbps (or 12.5 kbps). 2 Electrical characteristics table: Line A +5 V +-0.5 V, Line B -5 V +-0.5 V (relative to ground), differential voltage 10 V nominal, encoding Manchester Biphase-L (Bipolar Return to Zero), word length 32 bits, high data rate 100 kbps (bit time 10 us), low data rate 12.5 kbps (bit time 80 us), up to 20 receivers per transmitter, shielded twisted pair, maximum cable length about 200 m, unidirectional point-to-point, error code NRZ (non-return to zero) at fault level. 3 Structure of the 32-bit data word (Fig. 2) drawn with bit 32 at the left: P (bit 32, even parity, 1 bit), Label (8 bits, 0 to 255), Data field (19 bits), SDI (2 bits, 0 to 3), SSM (2 bits). 4 Example word (Fig. 3): P 0, Label 8D (1000 1101), Data 1A3F5 (000 1101000 0111110101), SDI 1 (01), SSM 2 (10); a differential waveform over time, bit time 10 us at 100 kbps.',
   'Bốn khung. 1 Mã hoá bit (Hình 1): bit 1 (cao) và bit 0 (thấp) vẽ trên Line A và Line B trong 10 us; chữ: ARINC 429 dùng mã hoá Manchester Biphase-L; mỗi bit có một chuyển mức ở giữa chu kỳ bit (5 us); bit 1: Line A mức cao (+V), Line B mức thấp (-V) trong nửa đầu bit; bit 0 thì ngược lại; mỗi bit kéo dài 10 us, ứng với 100 kbps (hoặc 12,5 kbps). 2 Bảng đặc tính điện: Line A +5 V +-0,5 V, Line B -5 V +-0,5 V (so với đất), điện áp vi sai danh định 10 V, mã hoá Manchester Biphase-L (Bipolar Return to Zero), độ dài từ 32 bit, tốc độ cao 100 kbps (thời gian bit 10 us), tốc độ thấp 12,5 kbps (thời gian bit 80 us), tối đa 20 bộ thu cho một bộ phát, cặp xoắn có bọc, chiều dài cáp tối đa khoảng 200 m, điểm-điểm một chiều, mã lỗi NRZ (không về không) ở mức lỗi. 3 Cấu trúc từ 32 bit (Hình 2) vẽ với bit 32 ở bên trái: P (bit 32, parity chẵn, 1 bit), Label (8 bit, 0 đến 255), trường Data (19 bit), SDI (2 bit, 0 đến 3), SSM (2 bit). 4 Từ ví dụ (Hình 3): P 0, Label 8D (1000 1101), Data 1A3F5 (000 1101000 0111110101), SDI 1 (01), SSM 2 (10); dạng sóng vi sai theo thời gian, thời gian bit 10 us ở 100 kbps.',
   numbers=['Line A +5 V +-0,5 V; Line B -5 V +-0,5 V', 'vi sai 10 V', '100 kbps = 10 us; 12,5 kbps = 80 us', 'cáp tối đa khoảng 200 m'],
   issues=['Không khớp nội bộ và với Tooley: slide ghi mã hoá ARINC 429 là "Manchester Biphase-L (Bipolar Return to Zero)", trong khi slide 3 và 13 của cùng bộ mô tả BPRZ; Tooley (mục Electrical Characteristics) cũng dùng BPRZ. Manchester và BPRZ là hai mã khác nhau (Module 05 đã ghi lỗi này).',
           'Không khớp với Tooley: slide ghi parity chẵn; ' + TOOLEY62,
           'Không khớp trong bộ: hình 2 vẽ thứ tự bit 32 (P), label ở bit 31 đến 24, data, SDI, SSM ở bit 2 đến 1; các slide 10, 15, 16, 17 và Tooley (tr.62) đặt label ở bit 1 đến 8, SDI ở bit 9 và 10, data ở bit 11 đến 29, SSM ở bit 30 và 31, parity ở bit 32.',
           'Đã kiểm: 8D hex = 1000 1101; 1A3F5 hex cần 17 bit (1 1010 0011 1111 0101), không phải 19 bit như trường data; ví dụ bị trộn các cách ghi.',
           'Đã kiểm: bit time 100 kbps = 10 us; 12,5 kbps = 80 us.']),
 s(15, 'content', 'Word format of ARINC 429',
   'Six panels. 1 Structure of a 32-bit word (Fig. 1): bits numbered 1 to 32, LSB transmitted first, MSB transmitted last; drawn as Label (8 bits), Data (19 bits), SDI (2 bits), Parity (1 bit), SSM (2 bits) from left to right. Transmission characteristics: each bit uses Manchester (bi-phase) coding; the most significant bit (bit 1 - LSB) is transmitted first and the least significant (bit 32 - MSB) last; data rate 12.5 kbps (low speed) or 100 kbps (high speed). 2 Fields table: Label 8 bits, Data 19, SDI 2, Parity 1 (odd parity bit for error detection), SSM 2. 3 Meaning of each field: Label (8 bits) identifies the type of data, values 0 to 255 (hex); Data (19 bits) signed, unsigned, BCD, binary, discrete; SDI (2 bits) source or destination, lets several devices share the bus using the label; Parity (1 bit) odd parity bit (total number of 1s in 32 bits is odd); SSM (2 bits) status of the data (00 failure, 01 no computed data, 10 functional test, 11 normal operation). 4 SSM status (example): 00 Failure Warning; 01 No Computed Data (data not valid); 10 Functional Test (system test in progress); 11 Normal Operation (data valid). 5 Transmission order: bit 1 is transmitted first, bit 32 last; order of fields on the bus from first to last: 8 (Label), 19 (Data), 2 (SDI), 1 (Parity), 2 (SSM). 6 Example word: Label 0110 1001 (8 bits), Data 19 bits, SDI 01, Parity 1, SSM 11. Notes: each system defines its own label and data format; the bit with the lowest index is sent first; bit time and voltage levels are defined in the ARINC 429 standard.',
   'Sáu khung. 1 Cấu trúc từ 32 bit (Hình 1): bit đánh số 1 đến 32, LSB truyền trước, MSB truyền sau; vẽ từ trái sang phải là Label (8 bit), Data (19 bit), SDI (2 bit), Parity (1 bit), SSM (2 bit). Đặc điểm truyền: mỗi bit dùng mã Manchester (hai pha); bit có trọng số lớn nhất (bit 1 - LSB) truyền trước và nhỏ nhất (bit 32 - MSB) truyền cuối; tốc độ 12,5 kbps (thấp) hoặc 100 kbps (cao). 2 Bảng các trường: Label 8 bit, Data 19, SDI 2, Parity 1 (bit parity lẻ để phát hiện lỗi), SSM 2. 3 Ý nghĩa từng trường: Label (8 bit) cho biết loại dữ liệu, giá trị 0 đến 255 (hex); Data (19 bit) có dấu, không dấu, BCD, nhị phân, rời rạc; SDI (2 bit) nguồn hoặc đích, cho nhiều thiết bị dùng chung bus nhờ label; Parity (1 bit) parity lẻ (tổng số bit 1 trong 32 bit là lẻ); SSM (2 bit) trạng thái dữ liệu (00 hỏng, 01 không có dữ liệu tính, 10 thử chức năng, 11 bình thường). 4 Trạng thái SSM (ví dụ): 00 cảnh báo hỏng; 01 không có dữ liệu tính (dữ liệu không hợp lệ); 10 thử chức năng (đang thử hệ thống); 11 hoạt động bình thường (dữ liệu hợp lệ). 5 Thứ tự truyền: bit 1 truyền trước, bit 32 truyền cuối; thứ tự các trường trên bus từ đầu đến cuối: 8 (Label), 19 (Data), 2 (SDI), 1 (Parity), 2 (SSM). 6 Từ ví dụ: Label 0110 1001 (8 bit), Data 19 bit, SDI 01, Parity 1, SSM 11. Ghi chú: mỗi hệ thống tự định nghĩa label và định dạng dữ liệu; bit có chỉ số thấp nhất được gửi trước; thời gian bit và mức điện áp do chuẩn ARINC 429 quy định.',
   issues=['Không khớp với Tooley: slide vẽ thứ tự trường Label, Data, SDI, Parity, SSM (SDI sau data, parity ở bit 30, SSM ở bit 31 và 32). Tooley Hình 4.11 (tr.62) và các slide 10, 16, 17 đặt: label bit 1 đến 8, SDI bit 9 và 10, data bit 11 đến 29, SSM bit 30 và 31, parity bit 32.',
           'Không khớp nội bộ: slide nói mã Manchester (hai pha) trong khi slide 13 mô tả BPRZ và Tooley dùng BPRZ.',
           'Không khớp nội bộ: câu "bit có trọng số lớn nhất (bit 1 - LSB) truyền trước" tự mâu thuẫn (bit 1 là LSB).',
           'Slide này ghi parity lẻ, khớp Tooley (tr.62); slide 10 và 14 ghi chẵn.']),
 s(16, 'content', 'ARINC 429 - Data types (BCD and BNR)',
   'Seven panels. 1 Structure of the 32-bit word with bit 32 at the left: P (parity, even parity, 1 bit), SSM (2 bits, bits 31 and 30), Data (19 bits), SDI (2 bits), Label (8 bits). 2 BCD encoding: 4 bits per decimal digit; the 19-bit data field can hold up to 5 decimal digits (5 x 4 = 20 bits with 1 bit unused); the most significant bit of the 19-bit field is unused (Sign) and the remaining 18 bits are used for digits; example encoding the number 19; fields SD (scale/discretisation, decimal point position), S (sign: 0 positive, 1 negative), CHAR 1 to CHAR 5 (4 bits each); table decimal digit to BCD code 0000 to 1001. 3 Example of a BCD data word: transmit +257 (5 digits, SD = 00) with CHAR1 0, CHAR2 2, CHAR3 5, CHAR4 7, CHAR5 0 (as read). 4 BNR encoding: signed integer in two\'s complement using 19 bits; bit 29 sign bit (0 positive, 1 negative); bit 28 used for SD or reserved; bits 27 to 11 magnitude field (17 bits); example encoding the value +100 (BNR, SD = 00). 5 SSM for BCD data: 00 plus, north, east, right, up, above (valid data, positive); 01 no computed data (data not valid); 10 functional test (in test mode); 11 minus, south, west, left, from, below (valid data, negative). 6 SDI (bits 10 and 9): 00 to 11 give source/destination 0 to 3. 7 Label (bits 8 to 1): 8-bit label identifies the data type, value 0 to 255 (defined by ARINC); common labels (decimal): 203 indicated airspeed (true air speed), 204 Mach number, 205 pressure altitude.',
   'Bảy khung. 1 Cấu trúc từ 32 bit với bit 32 ở bên trái: P (parity, chẵn, 1 bit), SSM (2 bit, bit 31 và 30), Data (19 bit), SDI (2 bit), Label (8 bit). 2 Mã hoá BCD: 4 bit cho mỗi chữ số thập phân; trường data 19 bit chứa tối đa 5 chữ số (5 x 4 = 20 bit, dư 1 bit); bit cao nhất của trường 19 bit không dùng (Sign) và 18 bit còn lại cho chữ số; ví dụ mã hoá số 19; các trường SD (tỉ lệ/rời rạc, vị trí dấu thập phân), S (dấu: 0 dương, 1 âm), CHAR 1 đến CHAR 5 (4 bit mỗi trường); bảng chữ số thập phân sang mã BCD 0000 đến 1001. 3 Ví dụ từ dữ liệu BCD: truyền +257 (5 chữ số, SD = 00) với CHAR1 0, CHAR2 2, CHAR3 5, CHAR4 7, CHAR5 0 (theo đọc). 4 Mã hoá BNR: số nguyên có dấu dạng bù hai dùng 19 bit; bit 29 là bit dấu (0 dương, 1 âm); bit 28 dùng cho SD hoặc dự phòng; bit 27 đến 11 là trường độ lớn (17 bit); ví dụ mã hoá giá trị +100 (BNR, SD = 00). 5 SSM cho dữ liệu BCD: 00 cộng, bắc, đông, phải, lên, trên (dữ liệu hợp lệ, dương); 01 không có dữ liệu tính (không hợp lệ); 10 thử chức năng (chế độ thử); 11 trừ, nam, tây, trái, từ, dưới (dữ liệu hợp lệ, âm). 6 SDI (bit 10 và 9): 00 đến 11 cho nguồn/đích 0 đến 3. 7 Label (bit 8 đến 1): label 8 bit cho biết loại dữ liệu, giá trị 0 đến 255 (do ARINC định nghĩa); label thường gặp (thập phân): 203 tốc độ chỉ thị (tốc độ thực), 204 số Mach, 205 độ cao áp suất.',
   issues=['Không khớp với Tooley: ' + TOOLEY62 + ' Slide ghi parity chẵn và label ở dạng thập phân (203, 204, 205). Tooley Hình 4.13 (tr.63) dùng label 103 cho tốc độ chọn.',
           'Không khớp nội bộ: nhãn 203 ghi "Indicated Airspeed (True Air Speed)" lẫn hai khái niệm khác nhau (tốc độ chỉ thị và tốc độ thực).',
           'Nghi vấn: ví dụ BCD +257 với SD = 00 đặt các CHAR là 0, 2, 5, 7, 0 (đọc từ ảnh nhỏ) có vẻ cho 02570 chứ không phải 257; cần đọc lại ở độ phân giải cao.']),
 s(17, 'content', 'ARINC 429 - Data formats (BNR example, sign representation)',
   'Five panels. 1 General format of a 32-bit word (Fig. 6, generalised BNR word format) drawn with bit 32 at the left: P (1 bit), SSM (2 bits), Data (19 bits), Pad (1 bit), SDI (2 bits), Label (8 bits); field table: Label 8 bits identifies the data type and meaning; SDI 2 bits source or destination; Pad 1 bit padding (usually 0); Data 19 bits actual data (numeric, BCD, characters); SSM 2 bits (normal, fail, no computed data); P (Parity) 1 bit odd parity so that the total number of 1 bits in the word is odd. 2 BNR example: the value 103 (positive) encoded in the 19-bit data field: label 103 (example label), SDI 00 (source 0), Pad 0, Data 19 bits "000 0000 1100111" (as read) for 103 decimal, bit 29 = 0 positive, SSM 11 (normal operation, valid data), P (Parity) = 0 chosen so the total number of 1s is odd. 3 Sign representation in BNR: two\'s complement for signed integers with 19 bits; bit 29 is the sign bit (0 positive, 1 negative); the numeric value is computed from the 19-bit field by the label definition (scale factor); unused bits are filled with 0. 4 Other data formats: BCD, character data, discrete data, mixed formats; labels 29 to 11 are used (as read). 5 Important notes: each label has a specific definition (data type, scale factor, meaning); bit 32 (parity) is always transmitted last; common SSM values 00 failure warning, 01 no computed data, 10 functional test, 11 normal operation.',
   'Năm khung. 1 Định dạng chung của từ 32 bit (Hình 6, định dạng BNR tổng quát) vẽ với bit 32 ở bên trái: P (1 bit), SSM (2 bit), Data (19 bit), Pad (1 bit), SDI (2 bit), Label (8 bit); bảng trường: Label 8 bit cho biết loại và ý nghĩa dữ liệu; SDI 2 bit nguồn hoặc đích; Pad 1 bit đệm (thường 0); Data 19 bit dữ liệu thực (số, BCD, ký tự); SSM 2 bit (bình thường, hỏng, không có dữ liệu tính); P (Parity) 1 bit parity lẻ để tổng số bit 1 trong từ là lẻ. 2 Ví dụ BNR: giá trị 103 (dương) mã trong trường data 19 bit: label 103 (label ví dụ), SDI 00 (nguồn 0), Pad 0, Data 19 bit "000 0000 1100111" (theo đọc) cho 103 thập phân, bit 29 = 0 là dương, SSM 11 (hoạt động bình thường, dữ liệu hợp lệ), P (Parity) = 0 chọn để tổng số bit 1 là lẻ. 3 Biểu diễn dấu trong BNR: bù hai cho số nguyên có dấu với 19 bit; bit 29 là bit dấu (0 dương, 1 âm); giá trị số tính từ trường 19 bit theo định nghĩa label (hệ số tỉ lệ); bit không dùng điền 0. 4 Các định dạng khác: BCD, dữ liệu ký tự, dữ liệu rời rạc, định dạng hỗn hợp; dùng label 29 đến 11 (theo đọc). 5 Lưu ý quan trọng: mỗi label có định nghĩa riêng (kiểu dữ liệu, hệ số tỉ lệ, ý nghĩa); bit 32 (parity) luôn truyền cuối; giá trị SSM thường gặp 00 cảnh báo hỏng, 01 không có dữ liệu tính, 10 thử chức năng, 11 bình thường.',
   issues=['Không khớp số học (đọc từ ảnh): hình 6 liệt kê P 1 + SSM 2 + Data 19 + Pad 1 + SDI 2 + Label 8 = 33 bit, không phải 32 như các slide 10, 15, 16 (8 + 2 + 19 + 2 + 1).',
           'Nghi vấn: dãy "000 0000 1100111" cho 103 chỉ có 14 chữ số trong khi trường data là 19 bit (đọc ở độ phân giải thấp); 103 = 1100111 (7 bit).',
           'Slide ghi parity lẻ, khớp Tooley (tr.62), và bảng SSM khớp slide 15 (00 hỏng, 11 bình thường). Slide 10 ghi ngược.']),
 s(18, 'thanks', 'Thank you very much for your attention', 'Closing slide: "Thank you very much for your attention" with the USTH logo.', 'Slide kết thúc: "Thank you very much for your attention" (cảm ơn rất nhiều đã chú ý) kèm logo USTH.'),
]
